DROP TABLE IF EXISTS `weapon`;

CREATE TABLE `weapon` (
  `item_id` decimal(65,0) NOT NULL default '0',
  `name` varchar(255) default NULL,
  `bodypart` varchar(255) default NULL,
  `crystallizable` varchar(255) default NULL,
  `weight` decimal(65,0) default NULL,
  `soulshots` decimal(65,0) default NULL,
  `spiritshots` decimal(65,0) default NULL,
  `material` varchar(255) default NULL,
  `crystal_type` varchar(255) default NULL,
  `p_dam` decimal(65,0) default NULL,
  `rnd_dam` decimal(65,0) default NULL,
  `weaponType` varchar(255) default NULL,
  `critical` decimal(65,0) default NULL,
  `hit_modify` decimal(65,5) default NULL,
  `avoid_modify` decimal(65,0) default NULL,
  `shield_def` decimal(65,0) default NULL,
  `shield_def_rate` decimal(65,0) default NULL,
  `atk_speed` decimal(65,0) default NULL,
  `mp_consume` decimal(65,0) default NULL,
  `m_dam` decimal(65,0) default NULL,
  `durability` decimal(65,0) default NULL,
  `price` decimal(65,0) default NULL,
  `crystal_count` int(255) default NULL,
  `sellable` varchar(255) default NULL,
  `icon` varchar(255) default NULL,
  PRIMARY KEY  (`item_id`)
) TYPE=MyISAM;


